// Licensed under the MIT License.

using System.Collections.Generic;
using System.Text.Json;
using System.Text.Json.Serialization;

namespace Azure.ResourceManager
{
    [JsonSourceGenerationOptions]
    [JsonSerializable(typeof(Dictionary<string, Dictionary<string, JsonElement>>))]
    internal partial class ArmManagerModelContext : JsonSerializerContext { }
}
```

Then in `ArmClientOptions.cs`, replace:
```csharp
var allProfile = JsonSerializer.Deserialize<Dictionary<string, Dictionary<string, JsonElement>>>(span);
```
with:
```csharp
var allProfile = JsonSerializer.Deserialize(span, ArmManagerModelContext.Default.DictionaryStringDictionaryStringJsonElement);
```

Please implement ALL of these fixes. Read each file before editing to verify the exact code.

